/// Set one role by its TUI name (a `<base>/themes/<name>` file's keys).
/// False for a key that is not a role.
pub fn set(raw: &mut Raw, key: &str, c: u32) -> bool {
    match key {
        "code_fg" => raw.code_fg = c,
        "code_bg" => raw.code_bg = c,
        "heading_color" => raw.heading_color = c,
        "quote_color" => raw.quote_color = c,
        "list_bullet_color" => raw.list_bullet_color = c,
        "table_border_color" => raw.table_border_color = c,
        "table_header_color" => raw.table_header_color = c,
        "table_cell_color" => raw.table_cell_color = c,
        "bg" => raw.bg = c,
        "message_bg" => raw.message_bg = c,
        "border" => raw.border = c,
        "border_active" => raw.border_active = c,
        "muted" => raw.muted = c,
        "system_msg" => raw.system_msg = c,
        "user_color" => raw.user_color = c,
        "user_bg" => raw.user_bg = c,
        "claude_label" => raw.claude_label = c,
        "claude_text" => raw.claude_text = c,
        "thinking_color" => raw.thinking_color = c,
        "tool_label" => raw.tool_label = c,
        "tool_param" => raw.tool_param = c,
        "tool_result_color" => raw.tool_result_color = c,
        "tool_result_ok" => raw.tool_result_ok = c,
        "error_color" => raw.error_color = c,
        "warning_color" => raw.warning_color = c,
        "header_fg" => raw.header_fg = c,
        "status_streaming" => raw.status_streaming = c,
        "status_ready" => raw.status_ready = c,
        "help_fg" => raw.help_fg = c,
        "input_fg" => raw.input_fg = c,
        "prompt_fg" => raw.prompt_fg = c,
        "separator" => raw.separator = c,
        "cost_color" => raw.cost_color = c,
        "subagent_border" => raw.subagent_border = c,
        "subagent_name" => raw.subagent_name = c,
        "subagent_status" => raw.subagent_status = c,
        "subagent_done" => raw.subagent_done = c,
        "subagent_time" => raw.subagent_time = c,
        "event_icon" => raw.event_icon = Some(c),
        "event_source" => raw.event_source = Some(c),
        "event_text" => raw.event_text = Some(c),
        "event_critical" => raw.event_critical = Some(c),
        "tool_bash" => raw.tool_bash = Some(c),
        "tool_read" => raw.tool_read = Some(c),
        "tool_write" => raw.tool_write = Some(c),
        "tool_edit" => raw.tool_edit = Some(c),
        "tool_grep" => raw.tool_grep = Some(c),
        "tool_find" => raw.tool_find = Some(c),
        "tool_ls" => raw.tool_ls = Some(c),
        "tool_subagent" => raw.tool_subagent = Some(c),
        "tool_ext" => raw.tool_ext = Some(c),
        "tool_generic" => raw.tool_generic = Some(c),
        "tool_input_bg" => raw.tool_input_bg = Some(c),
        "tool_output_bg" => raw.tool_output_bg = Some(c),
        _ => return false,
    }
    true
}
